def classify2(t,w):
    if t in SAMPLE_EXACT or t.startswith(SAMPLE_PREFIX): return ('DATA','DATA — sample content written by the template author, technician or ShopCoach in the design (instruction text, note, photo caption, drafted line, template or field name)')
    if t.startswith(PROSE_PREFIX): return ('DESIGN NOTE','DESIGN NOTE — designer caption/annotation as rendered (sweep text), not product UI text')
    if re.match(r'^(Tire pressure|Tread depth|Brake pad|Brake lining|Push-rod travel) [\d.—]',t): return ('DATA','DATA — rendered report row values')
    return None

def classify(t,w,lib,tagsline):
    h=classify2(t,w)
    if h: return h
    if t in OV: return OV[t]
    if t.startswith('Bulletin SB-') or 'Appendix G' in t or t.startswith(('Free stroke','Air pressure at or above','Record both figures','Measure the outside diameter','Worn brake lining','Enter both figures','Under FMCSA','Re-check free stroke')): return ('DATA','DATA — content of the sample attached PDF shown in the D4 viewer')
    if w.startswith('sweep ') and (t.startswith('#') or t.startswith('=====')): return ('OUT-OF-SCOPE','OUT-OF-SCOPE — sweep tool page/file header line, not design text')
    return None
rows=[]
for src,lst in (('main',[r for r in main['rows'] if not r['in_a_case']]),('supplement',[r for r in supp if not r['in_a_case']])):
    for r in lst:
        t=r['text']; w=r['where']; lib=(src=='main' and not r['on_a_board'])
        hit=classify(t,w,lib,'')
        if hit: cls,why=hit
        else:
            ww=w if ('/' in w or w.startswith(('flow','sweep','image'))) else '../../dvi-new/'+w
            rl=raw(ww) if not w.startswith(('flow','sweep','image')) else ''
            tags=set(x.split()[0] for x in re.findall(r'class="([a-z0-9 -]+)"',rl))
            cls=why=''
            if lib: cls='OUT-OF-SCOPE'; why=('support.js/doc-page.js design-tool runtime' if ('support.js' in w or 'doc-page.js' in w) else 'design-system library (_ds)')+': text no DVI V2 board shows (no board uses a bundle component)'
            elif 'image-and-pdf-texts' in w:
                img=mp.get(int(w.rsplit(':',1)[1]),'?')
                if SLACK_IMG.search(img): cls,why='DESIGN NOTE',f'stakeholder feedback in {img} (adopted as PRD S13-R3/R9/R10; design R1 follows)'
                elif BUILD_IMG.search(img) or img.startswith('2026-08-17 20.27.42'): cls,why='OUT-OF-SCOPE',f'build reference screenshot {img} (current/dev build supplied as design input; not the 14 Oct design; expected results come from the PRD, Rule 57)'
                else: cls,why='DESIGN NOTE',f'superseded earlier design draft or crop: {img} (replaced by the 14 Oct boards)'
            elif 'Marketing Slides' in w: cls,why='OUT-OF-SCOPE','Marketing Slides deck: promotional material, not product UI (no PRD story covers it)'
            elif 'Mark OK Explorations' in w: cls,why='DESIGN NOTE','Mark OK Explorations: design options under study; the decision is PRD S18-R1'
            elif src=='main' and r.get('class'): cls,why='DATA','date, amount, VIN or time (tool pre-mark)'
            elif tags & CAPTION_CLS or '<h2' in rl or '<p ' in rl or '<p>' in rl or 'data-screen-label' in rl or SCREEN_ID.match(t) or SCREEN_ID2.match(t) or t.startswith('SV-8181') or re.match(r'^\d+ · ',t) or ('glab' in tags and (' · ' in t or (t.isupper() and len(t)>14))):
                cls,why='DESIGN NOTE','designer caption/annotation/board title or screen id, not product UI text'
            elif DATA_RE.match(t) or re.match(r'^[\d.,/ ]+(in\.|psi|hrs?|hr labor|parts?|mm|ft-lbs?)$',t) or re.fullmatch(r'S\d?-\d+|\d+ days? ago|Tires|ft-lbs|ft-lb|Leak-test-steps\.pdf|ShopView|\+ Add|1 hr|Instrukcije|Somenting|Testing this like crazy',t):
                cls,why='DATA','sample record data (person, company, number, measurement, file, date, work order, sample label)'
            elif w.startswith('flow') or w.startswith('sweep'):
                cls,why='',''
        if cls in ('SPEC-CONFLICT',) and why in SC: why=why+' '+SC[why][0]
        if cls=='CASE-NEEDED': pass
        rows.append({'source':src,'text':t,'where':w.replace('../../dvi-new/',''),'class':cls,'reason':why})
